package com.curso.services;
import com.curso.domains.*;import com.curso.domains.enums.TipoTransacao;import org.junit.jupiter.api.Test;import java.math.BigDecimal;import java.time.LocalDateTime;import java.util.List;import static org.junit.jupiter.api.Assertions.*;
class CalculadoraPosicaoTest{private final CalculadoraPosicao c=new CalculadoraPosicao();private final Usuario u=new Usuario(1L,"U","u@x.com","1","h");private final Ativo a=new Ativo(1L,"PETR4","Petrobras","B3");private final Corretora corretora=new Corretora(1L,"XP","XP Investimentos",true,false);private Transacao t(TipoTransacao tipo,String q,String v){return new Transacao(null,u,a,corretora,tipo,new BigDecimal(q),new BigDecimal(v),LocalDateTime.now());}
 @Test void calculaMediaPonderada(){var p=c.calcular(List.of(t(TipoTransacao.COMPRA,"10","20"),t(TipoTransacao.COMPRA,"5","26")));assertEquals(0,p.quantidade().compareTo(new BigDecimal("15")));assertEquals(0,p.precoMedio().compareTo(new BigDecimal("22")));}
 @Test void vendaParcialMantemMediaEZeragemZera(){var parcial=c.calcular(List.of(t(TipoTransacao.COMPRA,"15","22"),t(TipoTransacao.VENDA,"5","30")));assertEquals(0,parcial.precoMedio().compareTo(new BigDecimal("22")));var zero=c.calcular(List.of(t(TipoTransacao.COMPRA,"15","22"),t(TipoTransacao.VENDA,"15","30")));assertEquals(0,zero.quantidade().signum());assertEquals(0,zero.precoMedio().signum());}}
